def _emit_join_elements(op: dict, ver: str, stamp: str, isolation: str='atomic') -> tuple[str, str, str, str]:
    oid = op['id']
    s = _safe(oid)

    def _resolve(field: str, var: str) -> str:
        sel = op[field]
        if sel['by'] == 'ref':
            return f"__{var}_{s} = (Element)__el_{_safe(sel['value'])};"
        return f"__{var}_{s} = doc.GetElement({_eid(sel['value'], ver, oid)});
if (__{var}_{s} == null) {{ {refuse_stmt(oid, _cs(field + ': элемент не найден (модель изменилась после grounding)'), isolation)} }}"
    decl = f'Element __ja_{s} = null;
Element __jb_{s} = null;
bool __jpre_{s} = false;'
    create = f"""// join_elements {cs_line_comment_fragment(oid)}
{_resolve('first', 'ja')}
{_resolve('second', 'jb')}
if (__ja_{s}.Id == __jb_{s}.Id) {{ {refuse_stmt(oid, _cs('first и second — один и тот же элемент: соединять нечего'), isolation)} }}
try {{ __jpre_{s} = JoinGeometryUtils.AreElementsJoined(doc, __ja_{s}, __jb_{s}); }}
catch (Exception __jq_{s}) {{ {refuse_stmt(oid, '"не удалось спросить, соединены ли элементы: " + __jq_' + s + '.Message', isolation)} }}
if (!__jpre_{s})
{{
    try {{ JoinGeometryUtils.JoinGeometry(doc, __ja_{s}, __jb_{s}); }}
    catch (Exception __jx_{s})
    {{
        if (__jx_{s}.Message.IndexOf("cannot be joined", StringComparison.OrdinalIgnoreCase) >= 0)
        {{ {refuse_stmt(oid, '"элементы НЕ ИМЕЮТ ОБЩЕЙ ГРАНИ для соединения (Revit: cannot be joined) — это факт о паре (не касаются, либо стык уже сведён автоматически), а не отказ эмиссии: " + __jx_' + s + '.Message', isolation)} }}
        else
        {{ {refuse_stmt(oid, '"соединить не удалось (JoinGeometry), причина не «cannot be joined»: " + __jx_' + s + '.Message', isolation)} }}
    }}
}}"""
    post = [WitnessCheck(obligation_key='elements_joined', reader_cs='', verdict_cs=f"    bool __jok_{s} = false;
    try {{ __jok_{s} = JoinGeometryUtils.AreElementsJoined(doc, __ja_{s}, __jb_{s}); }} catch {{ __jok_{s} = false; }}
    if (!__jok_{s})
        __post.Add({_cs(oid + ': элементы НЕ соединены после JoinGeometry (semantic, re-read)')});
", message='элементы не соединены после JoinGeometry (semantic, re-read)', style='guard')]
    readback = f'// witness {cs_line_comment_fragment(oid)}
{{
    var __rb = new Dictionary<string, object>();
    var __jids_{s} = new List<string>();
    __jids_{s}.Add(__ja_{s}.Id.ToString());
    __jids_{s}.Add(__jb_{s}.Id.ToString());
    __rb["joined_ids"] = __jids_{s};
    __rb["already_joined"] = __jpre_{s};
    __results[{_cs(oid)}] = __rb;
}}'
    return (decl, create, post, readback)

def _emit_move_elements(op: dict, ver: str, stamp: str, isolation: str='atomic') -> tuple[str, str, str, str]:
    oid = op['id']
    s = _safe(oid)
    targets = op['targets']
    dx, dy, dz = op['delta_mm']
    htol = tolerance('move_elements', 'location_mm')
    resolve_blocks = []
    for i, sel in enumerate(targets):
        label = f'targets[{i}]'
        if sel['by'] == 'ref':
            get_line = f"Element __mte_{s} = (Element)__el_{_safe(sel['value'])};"
        else:
            get_line = f"Element __mte_{s} = doc.GetElement({_eid(sel['value'], ver, oid)});
    if (__mte_{s} == null) {{ {refuse_stmt(oid, _cs(label + ': элемент не найден (модель изменилась после grounding)'), isolation)} }}"
        resolve_blocks.append(f"{{
    {get_line}
    if (__mte_{s}.Pinned) {{ {refuse_stmt(oid, _cs(label + ': элемент закреплён (Pinned) — перенос невозможен'), isolation)} }}
    __mtIds_{s}.Add(__mte_{s}.Id);
    __mtEls_{s}.Add(__mte_{s});
    var __mtlp_{s} = __mte_{s}.Location as LocationPoint;
    var __mtlc_{s} = __mte_{s}.Location as LocationCurve;
    __mtBeforePt_{s}.Add(__mtlp_{s} != null ? __mtlp_{s}.Point : null);
    __mtBefore0_{s}.Add(__mtlc_{s} != null ? __mtlc_{s}.Curve.GetEndPoint(0) : null);
    __mtBefore1_{s}.Add(__mtlc_{s} != null ? __mtlc_{s}.Curve.GetEndPoint(1) : null);
    ConnectorManager __mtcm_{s} = null;
    MEPCurve __mtmc_{s} = __mte_{s} as MEPCurve;
    FamilyInstance __mtfi_{s} = __mte_{s} as FamilyInstance;
    if (__mtmc_{s} != null) __mtcm_{s} = __mtmc_{s}.ConnectorManager;
    else if (__mtfi_{s} != null && __mtfi_{s}.MEPModel != null) __mtcm_{s} = __mtfi_{s}.MEPModel.ConnectorManager;
    if (__mtcm_{s} != null)
        foreach (Connector __mtc_{s} in __mtcm_{s}.Connectors)
            if (__mtc_{s}.IsConnected) __mtConnBefore_{s}++;
    var __mtins_{s} = new List<string>();
    HostObject __mtho_{s} = __mte_{s} as HostObject;
    if (__mtho_{s} != null)
        foreach (ElementId __mtii_{s} in __mtho_{s}.FindInserts(true, true, false, false))
            __mtins_{s}.Add(__mtii_{s}.ToString());
    __mtInsBefore_{s}.Add(__mtins_{s});
    var __mtjn_{s} = new List<string>();
    try {{ foreach (ElementId __mtji_{s} in JoinGeometryUtils.GetJoinedElements(doc, __mte_{s})) __mtjn_{s}.Add(__mtji_{s}.ToString()); }}
    catch {{ __mtJoinRead_{s} = false; }}
    __mtJoinBefore_{s}.Add(__mtjn_{s});
    foreach (ElementId __mtdi_{s} in __mte_{s}.GetDependentElements(new ElementClassFilter(typeof(Dimension))))
    {{
        Dimension __mtd_{s} = doc.GetElement(__mtdi_{s}) as Dimension;
        if (__mtd_{s} == null) continue;
        __mtDimsSeen_{s}++;
        if (__mtd_{s}.NumberOfSegments > 1) {{ __mtDimsMulti_{s}++; continue; }}
        if (__mtd_{s}.IsLocked) __mtLockedDims_{s}.Add(__mtdi_{s});
    }}
}}")
    decl = f'List<ElementId> __mtIds_{s} = new List<ElementId>();
List<Element> __mtEls_{s} = new List<Element>();
List<XYZ> __mtBeforePt_{s} = new List<XYZ>();
List<XYZ> __mtBefore0_{s} = new List<XYZ>();
List<XYZ> __mtBefore1_{s} = new List<XYZ>();
List<List<string>> __mtInsBefore_{s} = new List<List<string>>();
List<List<string>> __mtJoinBefore_{s} = new List<List<string>>();
List<ElementId> __mtLockedDims_{s} = new List<ElementId>();
bool __mtJoinRead_{s} = true;
int __mtDimsSeen_{s} = 0;
int __mtDimsMulti_{s} = 0;
int __mtConnBefore_{s} = 0;'
    create = f'// move_elements {cs_line_comment_fragment(oid)}
' + '
'.join(resolve_blocks) + f"""
XYZ __mtDelta_{s} = new XYZ(U({dx}), U({dy}), U({dz}));
try {{ ElementTransformUtils.MoveElements(doc, __mtIds_{s}, __mtDelta_{s}); }}
catch (Exception __ex_{s}) {{ {refuse_stmt(oid, f'"MoveElements: " + __ex_{s}.Message', isolation)} }}"""
    post = [WitnessCheck(obligation_key='location', reader_cs='', verdict_cs=f"    for (int __mti_{s} = 0; __mti_{s} < __mtEls_{s}.Count; __mti_{s}++)
    {{
        Element __mte2_{s} = __mtEls_{s}[__mti_{s}];
        var __mtlp2_{s} = __mte2_{s}.Location as LocationPoint;
        XYZ __mtbp_{s} = __mtBeforePt_{s}[__mti_{s}];
        if (__mtlp2_{s} != null && __mtbp_{s} != null &&
            (Math.Abs(MM(__mtlp2_{s}.Point.X) - (MM(__mtbp_{s}.X) + {dx})) > {htol} ||
             Math.Abs(MM(__mtlp2_{s}.Point.Y) - (MM(__mtbp_{s}.Y) + {dy})) > {htol} ||
             Math.Abs(MM(__mtlp2_{s}.Point.Z) - (MM(__mtbp_{s}.Z) + {dz})) > {htol}))
            __post.Add({_cs(oid + ': targets[')} + __mti_{s} + {_cs('] точка не сдвинулась на delta_mm (geometry)')});
        var __mtlc2_{s} = __mte2_{s}.Location as LocationCurve;
        XYZ __mtb0_{s} = __mtBefore0_{s}[__mti_{s}];
        XYZ __mtb1_{s} = __mtBefore1_{s}[__mti_{s}];
        if (__mtlc2_{s} != null && __mtb0_{s} != null && __mtb1_{s} != null)
        {{
            XYZ __mta_{s} = __mtlc2_{s}.Curve.GetEndPoint(0);
            XYZ __mtb_{s} = __mtlc2_{s}.Curve.GetEndPoint(1);
            if (Math.Abs(MM(__mta_{s}.X) - (MM(__mtb0_{s}.X) + {dx})) > {htol} ||
                Math.Abs(MM(__mta_{s}.Y) - (MM(__mtb0_{s}.Y) + {dy})) > {htol} ||
                Math.Abs(MM(__mta_{s}.Z) - (MM(__mtb0_{s}.Z) + {dz})) > {htol} ||
                Math.Abs(MM(__mtb_{s}.X) - (MM(__mtb1_{s}.X) + {dx})) > {htol} ||
                Math.Abs(MM(__mtb_{s}.Y) - (MM(__mtb1_{s}.Y) + {dy})) > {htol} ||
                Math.Abs(MM(__mtb_{s}.Z) - (MM(__mtb1_{s}.Z) + {dz})) > {htol})
                __post.Add({_cs(oid + ': targets[')} + __mti_{s} + {_cs('] концы не сдвинулись на delta_mm (geometry)')});
        }}
    }}
", message='target не сдвинулся на delta_mm (geometry)', stage='operation', tol=htol, style='plain'), WitnessCheck(obligation_key='connectors', reader_cs='', verdict_cs=f"    int __mtConnAfter_{s} = 0;
    foreach (Element __mte3_{s} in __mtEls_{s})
    {{
        ConnectorManager __mtcm2_{s} = null;
        MEPCurve __mtmc2_{s} = __mte3_{s} as MEPCurve;
        FamilyInstance __mtfi2_{s} = __mte3_{s} as FamilyInstance;
        if (__mtmc2_{s} != null) __mtcm2_{s} = __mtmc2_{s}.ConnectorManager;
        else if (__mtfi2_{s} != null && __mtfi2_{s}.MEPModel != null) __mtcm2_{s} = __mtfi2_{s}.MEPModel.ConnectorManager;
        if (__mtcm2_{s} != null)
            foreach (Connector __mtc2_{s} in __mtcm2_{s}.Connectors)
                if (__mtc2_{s}.IsConnected) __mtConnAfter_{s}++;
    }}
    if (__mtConnBefore_{s} != __mtConnAfter_{s})
        __post.Add({_cs(oid + ': подключённых коннекторов стало ')} + __mtConnAfter_{s} + {_cs(', было ')} + __mtConnBefore_{s} + {_cs(' (topology)')});
", message='connector count changed across targets (topology)', style='plain'), WitnessCheck(obligation_key='slope', reader_cs='', verdict_cs=f"    for (int __mtj_{s} = 0; __mtj_{s} < __mtEls_{s}.Count; __mtj_{s}++)
    {{
        Element __mte4_{s} = __mtEls_{s}[__mtj_{s}];
        var __mtlc3_{s} = __mte4_{s}.Location as LocationCurve;
        XYZ __mtb0b_{s} = __mtBefore0_{s}[__mtj_{s}];
        XYZ __mtb1b_{s} = __mtBefore1_{s}[__mtj_{s}];
        if (__mtlc3_{s} != null && __mtb0b_{s} != null && __mtb1b_{s} != null)
        {{
            double __mtSlopeBefore_{s} = MM(__mtb1b_{s}.Z) - MM(__mtb0b_{s}.Z);
            XYZ __mtA2_{s} = __mtlc3_{s}.Curve.GetEndPoint(0);
            XYZ __mtB2_{s} = __mtlc3_{s}.Curve.GetEndPoint(1);
            double __mtSlopeAfter_{s} = MM(__mtB2_{s}.Z) - MM(__mtA2_{s}.Z);
            if (Math.Abs(__mtSlopeAfter_{s} - __mtSlopeBefore_{s}) > {htol})
                __post.Add({_cs(oid + ': targets[')} + __mtj_{s} + {_cs('] наклон изменился (semantic)')});
        }}
    }}
", message='LocationCurve target slope changed (semantic)', tol=htol, style='plain'), WitnessCheck(obligation_key='hosted_inserts', reader_cs='', verdict_cs=f"    for (int __mtk_{s} = 0; __mtk_{s} < __mtEls_{s}.Count; __mtk_{s}++)
    {{
        HostObject __mtho2_{s} = __mtEls_{s}[__mtk_{s}] as HostObject;
        if (__mtho2_{s} == null) continue;
        var __mtnow_{s} = new HashSet<string>();
        foreach (ElementId __mtii2_{s} in __mtho2_{s}.FindInserts(true, true, false, false))
            __mtnow_{s}.Add(__mtii2_{s}.ToString());
        foreach (string __mtwas_{s} in __mtInsBefore_{s}[__mtk_{s}])
            if (!__mtnow_{s}.Contains(__mtwas_{s}))
                __post.Add({_cs(oid + ': targets[')} + __mtk_{s} + {_cs('] потерял размещённый в нём элемент ')} + __mtwas_{s} + {_cs(' (topology)')});
    }}
", message='host lost a door/window it carried (topology)', style='plain'), WitnessCheck(obligation_key='locked_dimensions', reader_cs='', verdict_cs=f"    foreach (ElementId __mtld_{s} in __mtLockedDims_{s})
    {{
        Dimension __mtd2_{s} = doc.GetElement(__mtld_{s}) as Dimension;
        if (__mtd2_{s} == null || !__mtd2_{s}.IsLocked)
            __post.Add({_cs(oid + ': замок размера ')} + __mtld_{s}.ToString() + {_cs(' не пережил перенос (topology)')});
    }}
", message='an authored dimension lock did not survive the move (topology)', style='plain')]
    readback = f'// witness {cs_line_comment_fragment(oid)}
{{
    var __rb = new Dictionary<string, object>();
    var __mtIdStrs_{s} = new List<string>();
    foreach (ElementId __mtrid_{s} in __mtIds_{s}) __mtIdStrs_{s}.Add(__mtrid_{s}.ToString());
    __rb["moved_ids"] = __mtIdStrs_{s};
    __rb["count"] = __mtIds_{s}.Count;
    var __mtjlost_{s} = new List<string>();
    for (int __mtm_{s} = 0; __mtm_{s} < __mtEls_{s}.Count; __mtm_{s}++)
    {{
        var __mtjnow_{s} = new HashSet<string>();
        try {{ foreach (ElementId __mtjj_{s} in JoinGeometryUtils.GetJoinedElements(doc, __mtEls_{s}[__mtm_{s}])) __mtjnow_{s}.Add(__mtjj_{s}.ToString()); }}
        catch {{ __mtJoinRead_{s} = false; }}
        foreach (string __mtjw_{s} in __mtJoinBefore_{s}[__mtm_{s}])
            if (!__mtjnow_{s}.Contains(__mtjw_{s})) __mtjlost_{s}.Add(__mtjw_{s});
    }}
    __rb["joins_lost_count"] = __mtjlost_{s}.Count;
    __rb["joins_lost"] = __mtjlost_{s}.GetRange(0, Math.Min({_NEIGHBOUR_ID_CAP}, __mtjlost_{s}.Count));
    __rb["joins_read"] = __mtJoinRead_{s};
    __rb["dims_dependent"] = __mtDimsSeen_{s};
    __rb["dims_locked"] = __mtLockedDims_{s}.Count;
    __rb["dims_multisegment_unjudged"] = __mtDimsMulti_{s};
    __results[{_cs(oid)}] = __rb;
}}'
    return (decl, create, post, readback)

def _emit_tag(op: dict, ver: str, stamp: str, isolation: str='atomic') -> tuple[str, str, str, str]:
    oid = op['id']
    s = _safe(oid)
    view_res = _annot_view_res(op, s, ver, oid, isolation)
    tgt_res = _annot_elem_res(op['target'], f'__tg_{s}', ver, oid, 'target', isolation).replace(f'Element __tg_{s} =', f'__tg_{s} =')
    u, w = op['at']
    pt_cs = docspace.emit_view2d_to_xyz_cs(f'__vw_{s}', u, w)
    leader = 'true' if op.get('leader') else 'false'
    g_tagtype = op.get('tag_type')
    decl = f'Element __el_{s} = null; Element __tg_{s} = null;
View __vw_{s} = null;'
    if g_tagtype is not None:
        if ver <= '2021':
            raise KirRefusal([Diagnostic(code=EMIT_UNSUPPORTED, op_id=oid, field_name='tag_type', message_ru=f'tag_type (явный тип марки) недоступен на Revit {ver} — IndependentTag.Create(symId,...) появился в 2022; опустите tag_type для версии по умолчанию по категории')])
        type_decl = _annot_elem_res(g_tagtype, f'__ttel_{s}', ver, oid, 'tag_type', isolation)
        create_call = f'__el_{s} = IndependentTag.Create(doc, __ttel_{s}.Id, __vw_{s}.Id, new Reference(__tg_{s}), {leader}, TagOrientation.Horizontal, {pt_cs});'
    else:
        type_decl = ''
        create_call = f'__el_{s} = IndependentTag.Create(doc, __vw_{s}.Id, new Reference(__tg_{s}), {leader}, TagMode.TM_ADDBY_CATEGORY, TagOrientation.Horizontal, {pt_cs});'
    spatial_create = f"    var __se_{s} = __tg_{s} as SpatialElement;
    if (__se_{s} != null)
    {{
        if (__se_{s}.Location == null || __se_{s}.Area <= 0.0)
            {{ {refuse_stmt(oid, _cs('цель — пространственный элемент, который НЕ РАЗМЕЩЁН (нет Location или нулевая площадь): маркировать нечего'), isolation)} }}
" + (f"        {refuse_stmt(oid, _cs('leader:true у пространственной марки в этой волне отказан: точка означала бы КОНЕЦ ВЫНОСКИ, а сверяется ГОЛОВА (дословно RevitAPI.xml про седьмой аргумент) — молчаливый сдвиг вместо марки'), isolation)}
" if op.get('leader') else '') + (f"""        var __uv_{s} = {docspace.emit_view2d_to_uv_cs(u, w)};
        var __rm_{s} = __se_{s} as Autodesk.Revit.DB.Architecture.Room;
        var __ar_{s} = __se_{s} as Area;
        var __sc_{s} = __se_{s} as Autodesk.Revit.DB.Mechanical.Space;
        if (__rm_{s} != null)
            __el_{s} = doc.Create.NewRoomTag(new LinkElementId(__rm_{s}.Id), __uv_{s}, __vw_{s}.Id);
        else if (__sc_{s} != null)
            __el_{s} = doc.Create.NewSpaceTag(__sc_{s}, __uv_{s}, __vw_{s});
        else if (__ar_{s} != null)
        {{
            var __vp_{s} = __vw_{s} as ViewPlan;
            if (__vp_{s} == null)
                {{ {refuse_stmt(oid, '"марка площади требует вид-план (ViewPlan), а in_view — " + __vw_' + s + '.ViewType.ToString()', isolation)} }}
            __el_{s} = doc.Create.NewAreaTag(__vp_{s}, __ar_{s}, __uv_{s});
        }}
        else
            {{ {refuse_stmt(oid, '"цель — SpatialElement рода " + __se_' + s + '.GetType().Name + ", а марки строятся только для помещения, площади и пространства"', isolation)} }}
""" + (f"""        if (__el_{s} != null)
            {{ try {{ __el_{s}.ChangeTypeId(__ttel_{s}.Id); }}
              catch (Exception __tex_{s}) {{ {refuse_stmt(oid, '"тип марки не принят пространственной маркой: " + __tex_' + s + '.Message', isolation)} }} }}
""" if g_tagtype is not None else '') + f'    }}
    else
    {{
        {create_call}
    }}
')
    create = f"""// create_tag {cs_line_comment_fragment(oid)}
{view_res}
{tgt_res}
{type_decl}
try {{
{spatial_create}}}
catch (Exception __ex_{s}) {{ {refuse_stmt(oid, f'"IndependentTag.Create: " + __ex_{s}.Message', isolation)} }}
if (__el_{s} == null) {{ {refuse_stmt(oid, _cs('IndependentTag.Create вернул null'), isolation)} }}
""" + _stamp_block(f'__el_{s}', f'{stamp}:{oid}')
    if ver >= '2022':
        bound_expr = f'    try
    {{
        foreach (Element __tel in __itg_{s}.GetTaggedLocalElements())
            if (__tel != null && __tel.Id.ToString() == __tg_{s}.Id.ToString()) {{ __bound_{s} = true; break; }}
    }} catch {{ }}
'
    else:
        bound_expr = f'    try {{ __bound_{s} = __itg_{s}.TaggedLocalElementId.ToString() == __tg_{s}.Id.ToString(); }}
    catch {{ }}
'
    htol = tolerance('create_tag', 'head_mm')
    post = [WitnessCheck(obligation_key='in_view', reader_cs='', verdict_cs=f"    if (__el_{s}.OwnerViewId.ToString() != __vw_{s}.Id.ToString())
        __post.Add({_cs(oid + ': tag belongs to wrong view (topology)')});
", message='tag belongs to wrong view (topology)', style='guard'), WitnessCheck(obligation_key='target_bound', reader_cs=f'    bool __bound_{s} = false;
    var __itg_{s} = __el_{s} as IndependentTag;
    var __rtg_{s} = __el_{s} as Autodesk.Revit.DB.Architecture.RoomTag;
    var __atg_{s} = __el_{s} as AreaTag;
    var __stg_{s} = __el_{s} as Autodesk.Revit.DB.Mechanical.SpaceTag;
    if (__rtg_{s} != null)
    {{ try {{ __bound_{s} = __rtg_{s}.Room != null && __rtg_{s}.Room.Id.ToString() == __tg_{s}.Id.ToString(); }} catch {{ }} }}
    else if (__atg_{s} != null)
    {{ try {{ __bound_{s} = __atg_{s}.Area != null && __atg_{s}.Area.Id.ToString() == __tg_{s}.Id.ToString(); }} catch {{ }} }}
    else if (__stg_{s} != null)
    {{ try {{ __bound_{s} = __stg_{s}.Space != null && __stg_{s}.Space.Id.ToString() == __tg_{s}.Id.ToString(); }} catch {{ }} }}
    else if (__itg_{s} != null)
' + bound_expr + f'    else
    {{ }}
', verdict_cs=f"    if (!__bound_{s})
        __post.Add({_cs(oid + ': марка не связана с target (semantic, VIEW-BINDING LAW: target не виден в in_view?)')});
", message='марка не связана с target (semantic)', style='guard'), WitnessCheck(obligation_key='head_at', reader_cs='', verdict_cs=f'    try
    {{
' + f'        XYZ __head_{s} = (__el_{s} as IndependentTag) != null
            ? ((IndependentTag)__el_{s}).TagHeadPosition
            : ((SpatialElementTag)__el_{s}).TagHeadPosition;
' + docspace.emit_xyz_to_view2d_cs(f'__vw_{s}', f'__head_{s}', f'__rel_{s}', f'__ou_{s}', f'__ow_{s}', indent=' ' * 8) + f"        if (Math.Abs(__ou_{s} - {round(u, 2)}) > {htol} || Math.Abs(__ow_{s} - {round(w, 2)}) > {htol})
            __post.Add({_cs(oid + ': tag head differs from at (geometry)')});
    }} catch {{ __post.Add({_cs(oid + ': tag head unreadable (geometry)')}); }}
", message='tag head differs from at (geometry)', tol=htol, style='else_block')]
    readback = f'// witness {cs_line_comment_fragment(oid)}
{{
    var __rb = new Dictionary<string, object>();
    __rb["id"] = __el_{s}.Id.ToString();
' + _stamp_readback(f'__el_{s}') + f'    __rb["tagged_id"] = __tg_{s}.Id.ToString();
    __results[{_cs(oid)}] = __rb;
}}'
    return (decl, create, post, readback)

def emit_program(grounded_ops: list[dict], revit_version: str, intent: str='', *, isolation: str='atomic', postconditions: str='strict', disallow_wall_joins: bool=False, stamp_scope: str='', lineage: str='', expected_document: Mapping[str, str] | None=None, expected_identities: Sequence[ElementIdentityProof] | None=None) -> str:
    if isolation not in ('atomic', 'per_op'):
        raise ValueError(f"isolation must be 'atomic' or 'per_op', got {isolation!r}")
    if postconditions not in ('strict', 'report'):
        raise ValueError(f"postconditions must be 'strict' or 'report', got {postconditions!r}")
    solo = [op for op in grounded_ops if op['op'] in spec.SOLO_OPS]
    if solo:
        if len(grounded_ops) != 1:
