    ux, uy = (dx / dlen, dy / dlen)
    nx, ny = (uy, -ux)
    if g_type and g_type.get('in_emit') == IN_EMIT_DEFAULT:
        rt = f"RoofType __rt_{s} = doc.GetElement(doc.GetDefaultElementTypeId(ElementTypeGroup.RoofType)) as RoofType;
