    world = [(float(x0) + u * ux, float(y0) + u * uy, z) for u, z in profile]
    geo = [f'CurveArray __ca_{s} = new CurveArray();']
    for k in range(len(world) - 1):
        a, b = (world[k], world[k + 1])
        geo.append(f'__ca_{s}.Append(Line.CreateBound(P({_mm(a[0])}, {_mm(a[1])}, {_mm(a[2])}), P({_mm(b[0])}, {_mm(b[1])}, {_mm(b[2])})));')
    decl = f'ExtrusionRoof __el_{s} = null; ReferencePlane __rp_{s} = null; XYZ __nrm_{s} = null; XYZ __org_{s} = null;'
