{rt}
{lv_res}
View __vw_{s} = doc.ActiveView;
if (__vw_{s} == null) {{ {refuse_stmt(oid, _cs('активного вида нет — опорную плоскость не на чем создать'), isolation)} }}
if (__vw_{s}.ViewType == ViewType.Legend || __vw_{s}.ViewType == ViewType.DraftingView || __vw_{s}.ViewType == ViewType.DrawingSheet) {{ {refuse_stmt(oid, _cs('активный вид — легенда, чертёжный вид или лист: на них опорная плоскость становится ВИДОВОЙ, и кровля привязалась бы к аннотации вместо модели; откройте модельный вид'), isolation)} }}
__org_{s} = P({_mm(x0)}, {_mm(y0)}, 0.0);
__rp_{s} = doc.Create.NewReferencePlane(__org_{s}, P({_mm(x1)}, {_mm(y1)}, 0.0), XYZ.BasisZ, __vw_{s});
if (__rp_{s} == null) {{ {refuse_stmt(oid, _cs('NewReferencePlane вернул null'), isolation)} }}
XYZ __rn_{s} = __rp_{s}.Normal;
if (__rn_{s} == null || __rn_{s}.GetLength() <= 0.0) {{ {refuse_stmt(oid, _cs('у созданной опорной плоскости нет нормали — направление выдавливания неопределимо'), isolation)} }}
__rn_{s} = __rn_{s}.Normalize();
double __sg_{s} = __rn_{s}.DotProduct(new XYZ({_mm(nx)}, {_mm(ny)}, 0.0)) >= 0.0 ? 1.0 : -1.0;
__nrm_{s} = __sg_{s} > 0.0 ? __rn_{s} : __rn_{s}.Negate();
double __ea_{s} = __sg_{s} > 0.0 ? U({_mm(start_mm)}) : U({_mm(-end_mm)});
double __eb_{s} = __sg_{s} > 0.0 ? U({_mm(end_mm)}) : U({_mm(-start_mm)});
" + '
'.join(geo) + f"
__el_{s} = doc.Create.NewExtrusionRoof(__ca_{s}, __rp_{s}, __lv_{s}, __rt_{s}, __ea_{s}, __eb_{s});
if (__el_{s} == null) {{ {refuse_stmt(oid, _cs('NewExtrusionRoof вернул null'), isolation)} }}
" + _stamp_block(f'__el_{s}', f'{stamp}:{oid}')
    post = [WitnessCheck(obligation_key='element_class', reader_cs=f'    var __rr_{s} = __el_{s} == null ? null : doc.GetElement(__el_{s}.Id) as ExtrusionRoof;
', verdict_cs=f"    if (__rr_{s} == null)
        __post.Add({_cs(oid + ': элемент не перечитывается из документа как ExtrusionRoof (semantic)')});
", message='элемент не перечитывается из документа как ExtrusionRoof (semantic)', style='guard'), WitnessCheck(obligation_key='base_level', reader_cs=f'    var __blp_{s} = __rr_{s} == null ? null : __rr_{s}.get_Parameter(BuiltInParameter.ROOF_BASE_LEVEL_PARAM);
