    }}
    double __vt_{s} = 2.0 * doc.Application.VertexTolerance;
', verdict_cs=f"    if (__lo_{s} == double.MaxValue)
        __post.Add({_cs(oid + ': у кровли нет тела — выдавливание не замерить (geometry)')});
    else if (Math.Abs(__lo_{s} - U({_mm(start_mm)})) > __vt_{s}
          || Math.Abs(__hi_{s} - U({_mm(end_mm)})) > __vt_{s})
        __post.Add({_cs(oid + ': выдавливание не от start_mm до end_mm по нормали плоскости (geometry)')});
", message='выдавливание не от start_mm до end_mm по нормали плоскости (geometry)', style='guard')]
    readback = f'// witness {cs_line_comment_fragment(oid)}
{{
    var __rb = new Dictionary<string, object>();
    __rb["id"] = __el_{s}.Id.ToString();
